    ctx.fillStyle=inbound>4?'#ff5a4a':'#ffc04a';
    var _exH=inbound+(inbound===1?' HOSTILE':' HOSTILES')+' CLOSING IN';
    extRowPlate(_exH,W/2,_exRow,_exR,_exBW);   // v32.xx (cw-hostplate), cw-hostcol
